package com.clinic.appointment.service;
import com.clinic.appointment.domain.OutboxEvent;import com.clinic.appointment.repository.OutboxEventRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.data.domain.PageRequest;import org.springframework.http.MediaType;import org.springframework.scheduling.annotation.Scheduled;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.client.RestClient;import java.time.Instant;import java.util.*;
@Service public class OutboxWorker{private final OutboxEventRepository outbox;private final RestClient client;private final String key;public OutboxWorker(OutboxEventRepository o,RestClient.Builder b,@Value("${clients.notification-service-url}")String url,@Value("${app.internal-api-key}")String key){outbox=o;client=b.baseUrl(url).build();this.key=key;}
 @Scheduled(fixedDelayString="${app.outbox-delay-ms:5000}")@Transactional public void publish(){for(OutboxEvent e:outbox.findByStatusInAndNextAttemptAtLessThanEqualOrderByNextAttemptAt(List.of(OutboxEvent.Status.PENDING,OutboxEvent.Status.RETRY),Instant.now(),PageRequest.of(0,25)))try{String path="MEDICATION_PLAN".equals(e.getTarget())?"/internal/notifications/medication-plans":"/internal/notifications/events";client.post().uri(path).header("X-Internal-Key",key).contentType(MediaType.APPLICATION_JSON).body(e.getPayload()).retrieve().toBodilessEntity();e.sent();}catch(Exception x){e.failed(x.getMessage());}}}
